import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    k = int(next(iterator))

    powers = []
    for _ in range(n):
        p = []
        for _ in range(k):
            p.append(int(next(iterator)))
        powers.append(p)

    candidates = []

    results = []

    for i in range(n):
        current = powers[i]

        if i == 0:
            candidates.append(current)
            results.append(1)
            continue

        new_candidates = [current]
        removed_indices = set()

        for idx, cand in enumerate(candidates):
            if idx in removed_indices:
                continue

            dominated = False
            for j in range(k):
                if cand[j] < current[j]:
                    dominated = True
                    break

            if dominated:
                new_candidates.append(current)
                break
            else:
                dominated_current = False
                for j in range(k):
                    if current[j] < cand[j]:
                        dominated_current = True
                        break

                if not dominated_current:
                    new_candidates.append(cand)
                    removed_indices.add(idx)

        candidates = new_candidates
        results.append(len(candidates))

    for res in results:
        print(res)

if __name__ == "__main__":
    main()
